41: const colorCache = new Map();
42: function css(color) {
43:   const c = color >>> 0;
44:   let s = colorCache.get(c);
45:   if (s === undefined) {
46:     const r = (c >>> 24) & 255;
47:     const g = (c >>> 16) & 255;
48:     const b = (c >>> 8) & 255;
49:     const a = c & 255;
50:     s = a === 255 ? `rgb(${r},${g},${b})` : `rgba(${r},${g},${b},${(a / 255).toFixed(4)})`;
51:     if (colorCache.size > 4096) colorCache.clear();
52:     colorCache.set(c, s);
53:   }
54:   return s;
55: }
