122: function initAudio() {
123:   if (audio.ctx) {
124:     if (audio.ctx.state === 'suspended') audio.ctx.resume().catch(() => {});
125:     return;
126:   }
127:   const Ctx = window.AudioContext || window.webkitAudioContext;
128:   if (!Ctx) return;
129:   try {
130:     audio.ctx = new Ctx();
131:   } catch (_) {
132:     return;
133:   }
134:   const ac = audio.ctx;
135:   audio.master = ac.createGain();
136:   audio.master.gain.value = audio.muted ? 0 : 0.8;
137:   audio.master.connect(ac.destination);
138:   audio.sfxBus = ac.createGain();
139:   audio.sfxBus.gain.value = 0.55;
140:   audio.sfxBus.connect(audio.master);
141:   audio.musicBus = ac.createGain();
142:   audio.musicBus.gain.value = 0.15;
143:   audio.musicBus.connect(audio.master);
144: 
145:   const len = Math.floor(ac.sampleRate * 0.9);
146:   audio.noiseBuf = ac.createBuffer(1, len, ac.sampleRate);
147:   const data = audio.noiseBuf.getChannelData(0);
148:   let seed = 0x1234567;
149:   for (let i = 0; i < len; i++) {
150:     seed = (seed * 1664525 + 1013904223) >>> 0;
151:     data[i] = (seed / 0xffffffff) * 2 - 1;
152:   }
153: 
154:   if (audio.mode) startMusic(audio.mode);
155: }
