166: function tone(freq, dur, type, gain, slideTo, when, bus) {
167:   const ac = audio.ctx;
168:   if (!ac) return;
169:   const t = when || ac.currentTime;
170:   const osc = ac.createOscillator();
171:   const g = ac.createGain();
172:   osc.type = type || 'sine';
173:   osc.frequency.setValueAtTime(Math.max(20, freq), t);
174:   if (slideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t + dur);
175:   g.gain.setValueAtTime(0.0001, t);
176:   g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.008);
177:   g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
178:   osc.connect(g);
179:   g.connect(bus || audio.sfxBus);
180:   osc.start(t);
181:   osc.stop(t + dur + 0.02);
182: }
