184: function noise(dur, gain, cutoff, when) {
185:   const ac = audio.ctx;
186:   if (!ac || !audio.noiseBuf) return;
187:   const t = when || ac.currentTime;
188:   const src = ac.createBufferSource();
189:   src.buffer = audio.noiseBuf;
190:   const filter = ac.createBiquadFilter();
191:   filter.type = 'lowpass';
192:   filter.frequency.setValueAtTime(cutoff || 1800, t);
193:   filter.frequency.exponentialRampToValueAtTime(Math.max(120, (cutoff || 1800) * 0.35), t + dur);
194:   const g = ac.createGain();
195:   g.gain.setValueAtTime(gain, t);
196:   g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
197:   src.connect(filter);
198:   filter.connect(g);
199:   g.connect(audio.sfxBus);
200:   src.start(t);
201:   src.stop(t + dur + 0.02);
202: }
