282: function startMusic(mode) {
283:   audio.mode = mode;
284:   if (!audio.ctx || audio.ctx.state !== 'running') return;
285:   if (audio.timer !== null) return;
286:   audio.nextNote = audio.ctx.currentTime + 0.08;
287:   audio.step = 0;
288:   audio.timer = setInterval(musicScheduler, 180);
289: }
290: 
291: function stopMusic() {
292:   if (audio.timer !== null) {
293:     clearInterval(audio.timer);
294:     audio.timer = null;
295:   }
296: }
297: 
298: function setMusic(mode) {
299:   const changed = audio.mode !== mode;
300:   audio.mode = mode;
301:   if (!audio.ctx) return;
302:   if (mode === 0) {
303:     stopMusic();
304:     return;
305:   }
306:   if (changed) {
307:     audio.step = 0;
308:     audio.nextNote = audio.ctx.currentTime + 0.1;
309:   }
310:   startMusic(mode);
311: }
312: 
313: function musicScheduler() {
314:   const ac = audio.ctx;
315:   if (!ac) return;
316:   if (ac.state !== 'running' || audio.mode === 0 || audio.muted) {
317:     if (audio.mode === 0) stopMusic();
318:     return;
319:   }
320:   const beat = MODE_BEAT[audio.mode] || 0.5;
321:   while (audio.nextNote < ac.currentTime + 0.45) {
322:     scheduleBeat(audio.mode, audio.step, audio.nextNote, beat);
323:     audio.step++;
324:     audio.nextNote += beat;
325:   }
326: }
327: 
328: function scheduleBeat(mode, step, when, beat) {
329:   const scale = SCALES[mode] || SCALES[1];
330:   const root = MODE_ROOT[mode] || 220;
331:   const bus = audio.musicBus;
332:   const n = scale[(step * 3 + Math.floor(step / 4)) % scale.length];
333:   const octave = step % 8 === 7 ? 12 : 0;
334:   const freq = root * Math.pow(2, (n + octave) / 12);
335:   // Sparse, gentle melody.
336:   if (mode === 3) {
337:     tone(freq, beat * 0.85, 'square', 0.05, freq * 0.94, when, bus);
338:     if (step % 2 === 0) tone(root * 0.5, beat * 1.6, 'sawtooth', 0.06, root * 0.47, when, bus);
339:     if (step % 4 === 2) noise(0.1, 0.05, 1800, when);
340:   } else {
341:     if (step % 2 === 0) tone(freq, beat * 0.95, 'triangle', 0.075, freq, when, bus);
342:     if (step % 4 === 0) tone(root * 0.5, beat * 1.7, 'sine', 0.07, root * 0.5, when, bus);
343:     if (step % 8 === 6) tone(freq * 1.5, beat * 0.8, 'sine', 0.045, freq * 1.5, when, bus);
344:   }
345: }
