351: const imports = {
352:   env: {
353:     js_rect(x, y, w, h, color) {
354:       ctx.fillStyle = css(color);
355:       ctx.fillRect(x, y, w, h);
356:     },
357:     js_rect_rot(cx, cy, w, h, angle, color) {
358:       ctx.save();
359:       ctx.translate(cx, cy);
360:       ctx.rotate(angle);
361:       ctx.fillStyle = css(color);
362:       ctx.fillRect(-w * 0.5, -h * 0.5, w, h);
363:       ctx.restore();
364:     },
365:     js_circle(x, y, r, color) {
366:       if (r <= 0) return;
367:       ctx.fillStyle = css(color);
368:       ctx.beginPath();
369:       ctx.arc(x, y, r, 0, Math.PI * 2);
370:       ctx.fill();
371:     },
372:     js_ellipse(x, y, rx, ry, color) {
373:       if (rx <= 0 || ry <= 0) return;
374:       ctx.fillStyle = css(color);
375:       ctx.beginPath();
376:       ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
377:       ctx.fill();
378:     },
379:     js_ring(x, y, r, width, color) {
380:       if (r <= 0) return;
381:       ctx.strokeStyle = css(color);
382:       ctx.lineWidth = Math.max(0.4, width);
383:       ctx.beginPath();
384:       ctx.arc(x, y, r, 0, Math.PI * 2);
385:       ctx.stroke();
386:     },
387:     js_line(x1, y1, x2, y2, width, color) {
388:       ctx.strokeStyle = css(color);
389:       ctx.lineWidth = Math.max(0.35, width);
390:       ctx.beginPath();
391:       ctx.moveTo(x1, y1);
392:       ctx.lineTo(x2, y2);
393:       ctx.stroke();
394:     },
395:     js_tri(x1, y1, x2, y2, x3, y3, color) {
396:       ctx.fillStyle = css(color);
397:       ctx.beginPath();
398:       ctx.moveTo(x1, y1);
399:       ctx.lineTo(x2, y2);
400:       ctx.lineTo(x3, y3);
401:       ctx.closePath();
402:       ctx.fill();
403:     },
404:     js_poly(ptr, count, color) {
405:       if (!count || !memory) return;
406:       const flat = new Float32Array(memory.buffer, ptr >>> 0, count * 2);
407:       ctx.fillStyle = css(color);
408:       ctx.beginPath();
409:       ctx.moveTo(flat[0], flat[1]);
410:       for (let i = 1; i < count; i++) ctx.lineTo(flat[i * 2], flat[i * 2 + 1]);
411:       ctx.closePath();
412:       ctx.fill();
413:     },
414:     js_text(x, y, size, color, align, weight, ptr, len) {
415:       if (!len || size <= 0.1) return;
416:       const s = str(ptr, len);
417:       ctx.font = fontFor(size, weight);
418:       ctx.fillStyle = css(color);
419:       ctx.textAlign = align === 1 ? 'center' : align === 2 ? 'right' : 'left';
420:       ctx.textBaseline = 'middle';
421:       ctx.fillText(s, x, y);
422:     },
423:     js_text_width(ptr, len, size, weight) {
424:       if (!len) return 0;
425:       ctx.font = fontFor(size, weight);
426:       return ctx.measureText(str(ptr, len)).width;
427:     },
428:     js_gradient(x, y, w, h, c1, c2, vertical) {
429:       const g = vertical
430:         ? ctx.createLinearGradient(x, y, x, y + h)
431:         : ctx.createLinearGradient(x, y, x + w, y);
432:       g.addColorStop(0, clearCss(c1));
433:       g.addColorStop(1, clearCss(c2));
434:       ctx.fillStyle = g;
435:       ctx.fillRect(x, y, w, h);
436:     },
437:     js_glow(x, y, r, color) {
438:       if (r <= 0) return;
439:       const c = color >>> 0;
440:       const rr = (c >>> 24) & 255;
441:       const gg = (c >>> 16) & 255;
442:       const bb = (c >>> 8) & 255;
443:       const aa = (c & 255) / 255;
444:       const g = ctx.createRadialGradient(x, y, 0, x, y, r);
445:       g.addColorStop(0, `rgba(${rr},${gg},${bb},${aa})`);
446:       g.addColorStop(0.45, `rgba(${rr},${gg},${bb},${aa * 0.5})`);
447:       g.addColorStop(1, `rgba(${rr},${gg},${bb},0)`);
448:       const old = ctx.globalCompositeOperation;
449:       ctx.globalCompositeOperation = 'lighter';
450:       ctx.fillStyle = g;
451:       ctx.beginPath();
452:       ctx.arc(x, y, r, 0, Math.PI * 2);
453:       ctx.fill();
454:       ctx.globalCompositeOperation = old;
455:     },
456:     js_minimap(ptr, w, h) {
457:       uploadMinimap(ptr, w, h);
458:     },
459:     js_minimap_draw(x, y, w, h, alpha) {
460:       if (!minimapW) return;
461:       ctx.save();
462:       ctx.globalAlpha = Math.max(0, Math.min(1, alpha));
463:       ctx.imageSmoothingEnabled = false;
464:       ctx.drawImage(minimapCanvas, x, y, w, h);
465:       ctx.restore();
466:     },
467:     js_vignette(strength) {
468:       const s = Math.max(0, Math.min(1.2, strength));
469:       const cx = viewW * 0.5;
470:       const cy = viewH * 0.5;
471:       const inner = Math.min(viewW, viewH) * 0.28;
472:       const outer = Math.max(viewW, viewH) * 0.72;
473:       const g = ctx.createRadialGradient(cx, cy, inner, cx, cy, outer);
474:       g.addColorStop(0, 'rgba(0,0,0,0)');
475:       g.addColorStop(0.62, `rgba(0,0,0,${0.06 * s})`);
476:       g.addColorStop(1, `rgba(0,0,0,${0.62 * s})`);
477:       ctx.fillStyle = g;
478:       ctx.fillRect(0, 0, viewW, viewH);
479:     },
480:     js_sfx(id, volume) {
481:       playSfx(id, volume);
482:     },
483:     js_music(mode) {
484:       setMusic(mode);
485:     },
486:     js_save(ptr, len) {
487:       try {
488:         const text = str(ptr, len);
489:         localStorage.setItem(SAVE_KEY, text);
490:         localStorage.setItem(SAVE_KEY + '.time', String(Date.now()));
491:         updateSaveNote(true);
492:       } catch (err) {
493:         console.warn('Terraforge: could not save', err);
494:       }
495:     },
496:     js_load_len() {
497:       try {
498:         const text = localStorage.getItem(SAVE_KEY);
499:         loadBytes = text ? new TextEncoder().encode(text) : new Uint8Array(0);
500:       } catch (_) {
501:         loadBytes = new Uint8Array(0);
502:       }
503:       return loadBytes.length;
504:     },
505:     js_load_read(ptr, len) {
506:       const n = Math.min(len, loadBytes.length);
507:       if (n > 0) new Uint8Array(memory.buffer, ptr >>> 0, n).set(loadBytes.subarray(0, n));
508:       return n;
509:     },
510:     js_show_title() {
511:       openTitle();
512:     },
513:     js_mute(muted) {
514:       audio.muted = !!muted;
515:       if (audio.master) {
516:         audio.master.gain.setTargetAtTime(audio.muted ? 0 : 0.8, audio.ctx.currentTime, 0.03);
517:       }
518:       const btn = document.getElementById('m-mute');
519:       if (btn) {
520:         btn.textContent = audio.muted ? '🔇' : '♪';
521:         btn.classList.toggle('on', audio.muted);
522:       }
523:       try {
524:         localStorage.setItem(MUTE_KEY, audio.muted ? '1' : '0');
525:       } catch (_) {}
526:     },
527:     js_log(ptr, len) {
528:       console.log('[terraforge]', str(ptr, len));
529:     },
530:   },
531: };
