300:     fn clamp_camera(&self, c: V2) -> V2 {
301:         let max_x = (world::W as f32 * TILE as f32 - self.view.x).max(0.0);
302:         let max_y = (world::H as f32 * TILE as f32 - self.view.y).max(0.0);
303:         V2::new(clamp(c.x, 0.0, max_x), clamp(c.y, 0.0, max_y))
304:     }
