315:     pub fn sky_light(&self) -> f32 {
316:         // Smoothly dim around dusk and dawn.
317:         let t = self.time;
318:         let day = if t < 0.03 {
319:             lerp(0.35, 0.7, t / 0.03)
320:         } else if t < 0.10 {
321:             lerp(0.7, 1.0, (t - 0.03) / 0.07)
322:         } else if t < 0.52 {
323:             1.0
324:         } else if t < 0.64 {
325:             lerp(1.0, 0.35, (t - 0.52) / 0.12)
326:         } else if t < 0.90 {
327:             0.33
328:         } else {
329:             lerp(0.33, 0.7, (t - 0.90) / 0.05)
330:         };
331:         day
332:     }
