462:     pub fn update(&mut self, dt: f32, input: &Input) {
463:         let dt = clamp(dt, 0.0, 0.05);
464:         self.title_phase += dt;
465:         self.shake = (self.shake - dt * 18.0).max(0.0);
466:         self.flash = (self.flash - dt * 2.4).max(0.0);
467:         self.hurt_vignette = (self.hurt_vignette - dt * 1.8).max(0.0);
468:         self.touch_mode = input.touch_mode;
469:         self.mouse_screen = input.mouse;
470: 
471:         match self.mode {
472:             Mode::Attract => {
473:                 self.update_attract(dt);
474:                 if input.press(KEY_ENTER) {
475:                     self.play();
476:                 }
477:             }
478:             Mode::Playing => {
479:                 if self.inv_open {
480:                     self.handle_inventory_ui(input);
481:                     self.update_ambient(dt);
482:                     self.update_camera(dt);
483:                 } else if self.map_open {
484:                     if input.press(KEY_M) || input.press(KEY_ESC) || input.mouse_pressed {
485:                         self.map_open = false;
486:                     }
487:                 } else {
488:                     self.update_playing(dt, input);
489:                 }
490:                 if input.press(KEY_ESC) {
491:                     self.toggle_pause();
492:                 }
493:             }
494:             Mode::Paused => {
495:                 self.handle_pause_ui(input);
496:                 if input.press(KEY_ESC) {
497:                     self.mode = Mode::Playing;
498:                 }
499:             }
500:             Mode::Dead => {
501:                 self.update_dead(dt, input);
502:             }
503:             Mode::Victory => {
504:                 self.update_victory(dt, input);
505:             }
506:         }
507: 
508:         // Toast lifetimes tick in every mode so they never stick around.
509:         for t in self.toasts.iter_mut() {
510:             t.life -= dt;
511:         }
512:         self.toasts.retain(|t| t.life > 0.0);
513:         if let Some(b) = self.banner.as_mut() {
514:             b.life -= dt;
515:             if b.life <= 0.0 {
516:                 self.banner = None;
517:             }
518:         }
519:         self.boss_intro = (self.boss_intro - dt).max(0.0);
520:     }
