522:     fn update_attract(&mut self, dt: f32) {
523:         self.time += dt / CYCLE_SECONDS * 0.35;
524:         if self.time >= 1.0 {
525:             self.time -= 1.0;
526:             self.day += 1;
527:         }
528:         let t = self.title_phase;
529:         let base = self.world.spawn;
530:         let px = base.x + (t * 0.06).sin() * 170.0;
531:         let py = base.y - self.view.y * 0.28 + (t * 0.3).sin() * 10.0;
532:         self.camera = self.clamp_camera(V2::new(px - self.view.x * 0.5, py));
533:         for p in self.particles.iter_mut() {
534:             p.update(dt);
535:         }
536:         self.particles.retain(|p| p.life > 0.0);
537:         self.ambient_timer -= dt;
538:         if self.ambient_timer <= 0.0 {
539:             self.ambient_timer = 0.35;
540:             self.spawn_ambient();
541:         }
542:         let music = 4;
543:         if music != self.music_mode {
544:             self.music_mode = music;
545:             gfx::music(music);
546:         }
547:     }
