549:     fn update_playing(&mut self, dt: f32, input: &Input) {
550:         self.stats.play_time += dt;
551:         self.time += dt / CYCLE_SECONDS;
552:         if self.time >= 1.0 {
553:             self.time -= 1.0;
554:             self.day += 1;
555:             self.banner("A NEW DAY", &format!("Day {}", self.day), 0.9, 0xF2D38A);
556:             gfx::sfx(SFX_BANNER, 0.5);
557:         }
558:         let night = self.is_night();
559:         if night != self.was_night {
560:             self.was_night = night;
561:             if night {
562:                 self.banner("NIGHT FALLS", "The dead are stirring", 0.85, 0xB8A8FF);
563:                 gfx::sfx(SFX_BANNER, 0.6);
564:             } else {
565:                 self.banner("DAWN BREAKS", "You survived the night", 0.9, 0xFFD9A0);
566:                 gfx::sfx(SFX_BANNER, 0.5);
567:             }
568:         }
569: 
570:         // Player movement.
571:         let hp_before = self.player.hp;
572:         let was_ground = self.player.on_ground;
573:         let vy_before = self.player.vel.y;
574:         let swimming = self.player.in_water > 0.05;
575:         let jumped = self.player.update(&self.world, input, dt);
576:         if jumped {
577:             gfx::sfx(SFX_JUMP, 0.35);
578:             let feet = self.player.feet();
579:             for i in 0..4 {
580:                 let p = Particle::new(
581:                     feet,
582:                     V2::new((hash2(i, 2, self.seed) - 0.5) * 40.0, -10.0),
583:                     0.35,
584:                     1.5,
585:                     0x9A8A70CC,
586:                 )
587:                 .gravity(80.0)
588:                 .drag(2.0);
589:                 self.particles.push(p);
590:             }
591:         }
592:         if !was_ground && self.player.on_ground && vy_before > 380.0 {
593:             let feet = self.player.feet();
594:             for i in 0..8 {
595:                 let dir = if i % 2 == 0 { -1.0 } else { 1.0 };
596:                 self.particles.push(
597:                     Particle::new(
598:                         feet,
599:                         V2::new(dir * (20.0 + hash2(i, 9, self.seed) * 60.0), -20.0),
600:                         0.5,
601:                         2.0,
602:                         0x8A7A60AA,
603:                     )
604:                     .gravity(140.0)
605:                     .drag(2.4),
606:                 );
607:             }
608:             if vy_before > 620.0 {
609:                 self.shake = (self.shake + 2.5).min(8.0);
610:             }
611:         }
612:         if swimming && self.particles.len() < 300 && self.rng.chance(0.25) {
613:             self.particles.push(
614:                 Particle::new(self.player.center(), V2::new(self.rng.range(-20.0, 20.0), -40.0), 0.5, 1.6, 0x8FD4FFCC)
615:                     .gravity(100.0)
616:                     .drag(2.0)
617:                     .circle(),
618:             );
619:         }
620:         if self.player.hp < hp_before {
621:             self.hurt_vignette = 1.0;
622:             self.regen_timer = 0.0;
623:         }
624:         self.regen_timer += dt;
625:         if self.regen_timer > 6.0 && self.player.hp > 0.0 && self.player.hp < self.player.max_hp {
626:             self.player.hp = (self.player.hp + 3.2 * dt).min(self.player.max_hp);
627:         }
628: 
629:         // Cactus contact.
630:         let feet = self.player.feet();
631:         let cx = (feet.x / TILE as f32) as i32;
632:         let cy = (feet.y / TILE as f32) as i32;
633:         for y in (cy - 1)..=(cy + 1) {
634:             for x in (cx - 1)..=(cx + 1) {
635:                 if self.world.get(x, y) == world::CACTUS
636:                     && self.player.invuln <= 0.0
637:                     && self.player.intersects_tile(x, y)
638:                 {
639:                     if self.player.hurt(7.0, (x as f32 + 0.5) * TILE as f32) {
640:                         gfx::sfx(SFX_HURT, 0.6);
641:                         self.shake = 3.0;
642:                     }
643:                 }
644:             }
645:         }
646: 
647:         // Hotbar selection and HUD interaction.
648:         let hotbar = ui::hotbar_layout(self);
649:         let hover_hotbar = hotbar.contains(input.mouse);
650:         if let Some(slot) = hotbar.slot_at(input.mouse) {
651:             if input.mouse_pressed {
652:                 self.inventory.selected = slot;
653:                 gfx::sfx(SFX_CLICK, 0.35);
654:             }
655:         }
656:         if input.wheel.abs() > 0.01 && !self.inv_open {
657:             let step = if input.wheel > 0.0 { 1 } else { HOTBAR - 1 };
658:             self.inventory.selected = (self.inventory.selected + step) % HOTBAR;
659:             gfx::sfx(SFX_CLICK, 0.3);
660:         }
661:         for i in 0..10 {
662:             if input.press(KEY_DIGIT_1 + if i == 9 { 9 } else { i }) {
663:                 // Digits 1..9 map to slots 0..8 and 0 maps to slot 9.
664:                 let slot = if i == 9 { 9 } else { i };
665:                 self.inventory.selected = slot;
666:                 gfx::sfx(SFX_CLICK, 0.3);
667:             }
668:         }
669:         if input.press(KEY_E) || input.press(KEY_C) {
670:             self.inv_open = !self.inv_open;
671:             self.mining = None;
672:         }
673: 
674:         // Camera and cursor.
675:         self.update_camera(dt);
676:         let mouse_world = V2::new(self.camera.x + input.mouse.x, self.camera.y + input.mouse.y);
677:         self.mouse_world = mouse_world;
678:         let ui_consumed = hover_hotbar
679:             || (self.touch_mode && input.mouse.y > self.view.y * 0.72)
680:             || ui::top_bar_contains(self, input.mouse);
681: 
682:         if !ui_consumed {
683:             self.handle_use(input, mouse_world, dt);
684:         } else {
685:             self.mining = None;
686:         }
687: 
688:         // Simulation.
689:         self.update_enemies(dt);
690:         self.update_bombs(dt);
691:         self.update_drops(dt);
692:         self.update_particles(dt);
693:         self.update_ambient(dt);
694:         self.spawn_logic(dt);
695: 
696:         // Keep the minimap texture in sync occasionally.
697:         if self.world.map_dirty {
698:             gfx::minimap(self.world.minimap.as_ptr(), world::W as u32, world::H as u32);
699:             self.world.map_dirty = false;
700:         }
701: 
702:         // Quest flags.
703:         if self.inventory.count(ItemId::Wood) > 0 {
704:             self.flags.got_wood = true;
705:         }
706: 
707:         // Death.
708:         if self.player.hp <= 0.0 && self.mode == Mode::Playing {
709:             self.player.dead = true;
710:             self.mode = Mode::Dead;
711:             self.death_timer = 0.0;
712:             self.stats.deaths += 1;
713:             self.mining = None;
714:             self.boss_active = false;
715:             self.enemies.retain(|e| !e.kind.is_boss());
716:             self.banner("YOU DIED", "The world is unkind", 1.0, 0xFF6A6A);
717:             gfx::sfx(SFX_DEATH, 0.8);
718:             self.shake = 8.0;
719:             self.save_game();
720:             return;
721:         }
722: 
723:         // Victory transition after the boss dies.
724:         if self.boss_defeated && self.mode == Mode::Playing {
725:             self.victory_timer -= dt;
726:             if self.victory_timer <= 0.0 {
727:                 self.mode = Mode::Victory;
728:                 self.death_timer = 0.0;
729:                 gfx::sfx(SFX_VICTORY, 0.9);
730:             }
731:         }
732: 
733:         // Music.
734:         let target = if self.mode == Mode::Victory {
735:             5
736:         } else if self.boss_active {
737:             3
738:         } else if night {
739:             2
740:         } else {
741:             1
742:         };
743:         if target != self.music_mode {
744:             self.music_mode = target;
745:             gfx::music(target);
746:         }
747: 
748:         // Autosave.
749:         self.save_timer -= dt;
750:         if self.save_timer <= 0.0 {
751:             self.save_timer = 20.0;
752:             self.save_game();
753:         }
754:     }
