756:     fn update_camera(&mut self, dt: f32) {
757:         let look = self.mouse_world.sub(self.player.center()).scale(0.055);
758:         let look = V2::new(clamp(look.x, -50.0, 50.0), clamp(look.y, -35.0, 35.0));
759:         let target = self
760:             .player
761:             .center()
762:             .add(look)
763:             .sub(V2::new(self.view.x * 0.5, self.view.y * 0.5));
764:         let target = self.clamp_camera(target);
765:         let k = 1.0 - (-8.0 * dt).exp();
766:         self.camera = self.camera.lerp(target, k);
767:     }
