835:     fn handle_use(&mut self, input: &Input, mouse_world: V2, dt: f32) {
836:         let item = self.inventory.selected_item();
837:         let Some(item) = item else {
838:             self.mining = None;
839:             return;
840:         };
841:         let tx = (mouse_world.x / TILE as f32).floor() as i32;
842:         let ty = (mouse_world.y / TILE as f32).floor() as i32;
843:         let pc = self.player.center();
844:         let tile_center = V2::new(tx as f32 * TILE as f32 + 8.0, ty as f32 * TILE as f32 + 8.0);
845:         let reach = dist(pc, tile_center) <= TILE as f32 * 6.2;
846: 
847:         let left = input.mouse_down;
848:         let right = input.right_down;
849: 
850:         match item.use_kind() {
851:             UseKind::Mine => {
852:                 if left && reach {
853:                     let t = self.world.get(tx, ty);
854:                     if t != world::AIR && t != world::WATER && t != world::BEDROCK {
855:                         let same = self.mining.as_ref().map(|m| m.x == tx && m.y == ty).unwrap_or(false);
856:                         if !same {
857:                             self.mining = Some(Mining { x: tx, y: ty, progress: 0.0 });
858:                         }
859:                         if let Some(m) = self.mining.as_mut() {
860:                             let hard = world::hardness(t);
861:                             m.progress += dt / hard.max(0.03);
862:                             if m.progress >= 1.0 {
863:                                 self.break_tile(tx, ty, true);
864:                                 self.mining = None;
865:                             } else if self.rng.chance(dt * 14.0) {
866:                                 let colors = tile_particle_colors(t);
867:                                 let pos = V2::new(
868:                                     tx as f32 * TILE as f32 + self.rng.range(2.0, 14.0),
869:                                     ty as f32 * TILE as f32 + self.rng.range(2.0, 14.0),
870:                                 );
871:                                 self.particles.push(
872:                                     Particle::new(pos, V2::new(self.rng.range(-45.0, 45.0), self.rng.range(-70.0, -10.0)), 0.4, 1.6, colors[0])
873:                                         .gravity(520.0),
874:                                 );
875:                                 if self.rng.chance(0.25) {
876:                                     gfx::sfx(SFX_MINE, 0.12);
877:                                 }
878:                             }
879:                         }
880:                     } else {
881:                         self.mining = None;
882:                     }
883:                 } else {
884:                     self.mining = None;
885:                 }
886:             }
887:             UseKind::Swing => {
888:                 self.mining = None;
889:                 if input.mouse_pressed || input.right_pressed {
890:                     self.swing_sword(item);
891:                 }
892:             }
893:             UseKind::Place => {
894:                 self.mining = None;
895:                 if input.mouse_pressed || input.right_pressed || (left && self.touch_mode) {
896:                     self.place_selected(tx, ty);
897:                 }
898:             }
899:             UseKind::Bomb => {
900:                 self.mining = None;
901:                 if input.mouse_pressed || input.right_pressed {
902:                     self.throw_bomb(mouse_world);
903:                 }
904:             }
905:             UseKind::Heal => {
906:                 self.mining = None;
907:                 if input.mouse_pressed || input.right_pressed {
908:                     self.drink_potion();
909:                 }
910:             }
911:             UseKind::Summon => {
912:                 self.mining = None;
913:                 if input.mouse_pressed || input.right_pressed {
914:                     self.summon_boss();
915:                 }
916:             }
917:             UseKind::None => {
918:                 self.mining = None;
919:             }
920:         }
921:     }
