923:     fn swing_sword(&mut self, item: ItemId) {
924:         if self.player.attack_cooldown > 0.0 {
925:             return;
926:         }
927:         self.player.attack_cooldown = 0.36;
928:         self.player.use_anim = 1.0;
929:         gfx::sfx(SFX_SWING, 0.45);
930:         let pc = self.player.center();
931:         let dir = self.player.facing;
932:         let ax = pc.x + if dir > 0.0 { 4.0 } else { -38.0 };
933:         let ay = pc.y - 14.0;
934:         let aw = 34.0;
935:         let ah = 36.0;
936:         let mut hits = 0;
937:         for i in 0..self.enemies.len() {
938:             if self.enemies[i].dead {
939:                 continue;
940:             }
941:             let (ex, ey, ew, eh) = self.enemies[i].aabb();
942:             if aabb_overlap(ax, ay, aw, ah, ex, ey, ew, eh) {
943:                 let dmg = item.sword_damage() as f32 * self.rng.range(0.85, 1.15);
944:                 let (kind, cx, cy) = {
945:                     let e = &self.enemies[i];
946:                     (e.kind, e.center().x, e.center().y)
947:                 };
948:                 let killed = self.enemies[i].hurt(dmg, 190.0, pc.x);
949:                 self.stats_damage_text(dmg, cx, cy - 10.0);
950:                 self.particles.push(
951:                     Particle::new(V2::new(cx, cy), V2::new(dir * 100.0, -30.0), 0.3, 3.0, 0xE8E0D0FF).spark(),
952:                 );
953:                 if killed {
954:                     self.kill_enemy(i);
955:                 } else if kind.is_boss() {
956:                     self.shake = (self.shake + 1.5).min(6.0);
957:                 }
958:                 hits += 1;
959:                 if hits >= 5 {
960:                     break;
961:                 }
962:             }
963:         }
964:         if hits > 0 {
965:             gfx::sfx(SFX_HIT, 0.65);
966:             self.shake = (self.shake + 1.2).min(5.0);
967:         }
968:     }
