970:     fn place_selected(&mut self, tx: i32, ty: i32) {
971:         let Some(stack) = self.inventory.selected_stack() else { return };
972:         let Some(tile) = stack.id.place_tile() else { return };
973:         if !World::in_bounds(tx, ty) {
974:             return;
975:         }
976:         let target = self.world.get(tx, ty);
977:         if target != world::AIR && target != world::WATER {
978:             return;
979:         }
980:         let pc = self.player.center();
981:         let tile_center = V2::new(tx as f32 * TILE as f32 + 8.0, ty as f32 * TILE as f32 + 8.0);
982:         if dist(pc, tile_center) > TILE as f32 * 6.2 {
983:             return;
984:         }
985:         // Don't place solid blocks inside the player.
986:         if world::is_solid(tile) && self.player.intersects_tile(tx, ty) {
987:             return;
988:         }
989:         let neighbor = self.world.solid(tx - 1, ty)
990:             || self.world.solid(tx + 1, ty)
991:             || self.world.solid(tx, ty - 1)
992:             || self.world.solid(tx, ty + 1)
993:             || self.world.get_wall(tx, ty) != world::WALL_NONE
994:             || self.world.platform(tx - 1, ty)
995:             || self.world.platform(tx + 1, ty)
996:             || self.world.platform(tx, ty - 1)
997:             || self.world.platform(tx, ty + 1);
998:         if !neighbor {
999:             return;
1000:         }
1001:         if tile == world::TORCH || tile == world::PLATFORM {
1002:             let attached = self.world.solid(tx, ty + 1)
1003:                 || self.world.get_wall(tx, ty) != world::WALL_NONE
1004:                 || (tile == world::PLATFORM
1005:                     && (self.world.solid(tx - 1, ty) || self.world.solid(tx + 1, ty)));
1006:             if !attached {
1007:                 return;
1008:             }
1009:         }
1010:         self.inventory.remove_selected_one();
1011:         self.world.set_tile(tx, ty, tile);
1012:         self.stats.blocks_placed += 1;
1013:         if tile == world::BENCH {
1014:             self.flags.placed_bench = true;
1015:             self.toast("Workbench placed", "Advanced recipes are now available", 0xF2CE8A);
1016:         }
1017:         if tile == world::TORCH {
1018:             gfx::sfx(SFX_PLACE, 0.6);
1019:         } else {
1020:             gfx::sfx(SFX_PLACE, 0.45);
1021:         }
1022:         let colors = tile_particle_colors(tile);
1023:         spawn_burst(&mut self.particles, tile_center, colors, 4, 50.0, 0.3, 1.4, tx as u32 ^ ty as u32);
1024:         self.player.use_anim = 0.55;
1025:         self.save_timer = self.save_timer.min(6.0);
1026:     }
