1495:     fn spawn_ambient(&mut self) {
1496:         if self.particles.len() > 400 {
1497:             return;
1498:         }
1499:         let pc = self.player.center();
1500:         let night = self.is_night();
1501:         let surface_y = self.world.surface_px(pc.x as i32);
1502:         let underground = pc.y > surface_y + 60.0;
1503:         if night && !underground {
1504:             // Fireflies drift over the grass.
1505:             let x = pc.x + self.rng.range(-self.view.x * 0.55, self.view.x * 0.55);
1506:             let y = self.world.surface_px(x as i32) - self.rng.range(8.0, 60.0);
1507:             if y > 0.0 {
1508:                 self.particles.push(
1509:                     Particle::new(
1510:                         V2::new(x, y),
1511:                         V2::new(self.rng.range(-8.0, 8.0), self.rng.range(-9.0, 2.0)),
1512:                         2.2,
1513:                         1.4,
1514:                         0xB8FF7ACC,
1515:                     )
1516:                     .gravity(-2.0)
1517:                     .drag(0.1)
1518:                     .circle(),
1519:                 );
1520:             }
1521:         } else if !underground && self.rng.chance(0.55) {
1522:             // Falling leaves.
1523:             let x = pc.x + self.rng.range(-self.view.x * 0.6, self.view.x * 0.6);
1524:             let y = self.camera.y + self.rng.range(-20.0, 60.0);
1525:             self.particles.push(
1526:                 Particle::new(
1527:                     V2::new(x, y),
1528:                     V2::new(self.rng.range(-16.0, 16.0), self.rng.range(8.0, 22.0)),
1529:                     2.8,
1530:                     2.0,
1531:                     if self.rng.chance(0.5) { 0x8AC46ACC } else { 0xB8D878CC },
1532:                 )
1533:                 .gravity(2.0)
1534:                 .drag(0.2)
1535:                 .leaf(),
1536:             );
1537:         } else if underground && self.rng.chance(0.45) {
1538:             // Dust motes in the caves.
1539:             let x = pc.x + self.rng.range(-self.view.x * 0.55, self.view.x * 0.55);
1540:             let y = pc.y + self.rng.range(-self.view.y * 0.5, self.view.y * 0.5);
1541:             self.particles.push(
1542:                 Particle::new(
1543:                     V2::new(x, y),
1544:                     V2::new(self.rng.range(-4.0, 4.0), self.rng.range(-8.0, -1.0)),
1545:                     2.5,
1546:                     1.0,
1547:                     0x8A90B080,
1548:                 )
1549:                 .gravity(0.0)
1550:                 .drag(0.0)
1551:                 .circle(),
1552:             );
1553:         }
1554:     }
