1556:     fn spawn_logic(&mut self, dt: f32) {
1557:         self.spawn_timer -= dt;
1558:         if self.spawn_timer > 0.0 {
1559:             return;
1560:         }
1561:         let night = self.is_night();
1562:         let cap = if night { 10 } else { 7 };
1563:         let alive = self.enemies.iter().filter(|e| !e.dead && !e.kind.is_boss()).count();
1564:         if alive >= cap || self.boss_active {
1565:             self.spawn_timer = 2.0;
1566:             return;
1567:         }
1568:         self.spawn_timer = if night { 1.6 + self.rng.range(0.0, 1.4) } else { 2.6 + self.rng.range(0.0, 2.2) };
1569:         let pc = self.player.center();
1570:         let surface_y = self.world.surface_px(pc.x as i32);
1571:         let underground = pc.y > surface_y + 90.0;
1572:         let side = if self.rng.chance(0.5) { -1.0 } else { 1.0 };
1573:         let spawn_x = pc.x + side * (self.view.x * 0.55 + self.rng.range(70.0, 260.0));
1574:         let sx = clamp_i((spawn_x / TILE as f32) as i32, 4, world::W - 5);
1575: 
1576:         if underground {
1577:             // Try to find a cave pocket around the player.
1578:             for _ in 0..14 {
1579:                 let tx = clamp_i((pc.x / TILE as f32) as i32 + self.rng.range_i(-32, 32), 3, world::W - 4);
1580:                 let ty = clamp_i((pc.y / TILE as f32) as i32 + self.rng.range_i(-18, 18), 3, world::H - 4);
1581:                 if self.world.get(tx, ty) != world::AIR || self.world.get(tx, ty - 1) != world::AIR {
1582:                     continue;
1583:                 }
1584:                 let floor = self.world.solid(tx, ty + 1);
1585:                 let kind = if floor && self.rng.chance(0.35) {
1586:                     EnemyKind::Zombie
1587:                 } else {
1588:                     EnemyKind::Bat
1589:                 };
1590:                 let (w, h) = kind.size();
1591:                 let e = Enemy::new(kind, V2::new(tx as f32 * TILE as f32 + (TILE as f32 - w) * 0.5, ty as f32 * TILE as f32 + TILE as f32 - h));
1592:                 self.enemies.push(e);
1593:                 return;
1594:             }
1595:         } else {
1596:             let top = self.world.surface_px(sx);
1597:             let mut ty = (top / TILE as f32) as i32 - 1;
1598:             // Move up until there is space.
1599:             let mut guard = 0;
1600:             while guard < 6 && self.world.solid(sx, ty) {
1601:                 ty -= 1;
1602:                 guard += 1;
1603:             }
1604:             if self.world.water(sx, ty) || self.world.solid(sx, ty) || self.world.solid(sx, ty - 1) {
1605:                 return;
1606:             }
1607:             let kind = if night && self.rng.chance(0.62) { EnemyKind::Zombie } else { EnemyKind::Slime };
1608:             let (w, h) = kind.size();
1609:             let e = Enemy::new(
1610:                 kind,
1611:                 V2::new(sx as f32 * TILE as f32 + (TILE as f32 - w) * 0.5, ty as f32 * TILE as f32 + TILE as f32 - h),
1612:             );
1613:             self.enemies.push(e);
1614:         }
1615:     }
