1683:     pub fn craft(&mut self, index: usize) {
1684:         let Some(recipe) = RECIPES.get(index) else { return };
1685:         let bench = self.world.bench_near(self.player.center().x, self.player.center().y, 6);
1686:         if recipe.bench && !bench {
1687:             self.toast("Workbench required", "Place a workbench nearby to craft this", 0xFFB070);
1688:             gfx::sfx(SFX_CLICK, 0.3);
1689:             return;
1690:         }
1691:         for input in recipe.inputs.iter().flatten() {
1692:             if self.inventory.count(input.0) < input.1 {
1693:                 self.toast("Not enough materials", recipe.hint, 0xFFB070);
1694:                 gfx::sfx(SFX_CLICK, 0.3);
1695:                 return;
1696:             }
1697:         }
1698:         for input in recipe.inputs.iter().flatten() {
1699:             self.inventory.consume(input.0, input.1);
1700:         }
1701:         let left = self.inventory.add(recipe.output, recipe.out_count);
1702:         if left > 0 {
1703:             self.spawn_drop(
1704:                 self.player.center(),
1705:                 recipe.output,
1706:                 left,
1707:             );
1708:         }
1709:         if recipe.output == ItemId::Bench {
1710:             self.flags.crafted_bench = true;
1711:         }
1712:         if recipe.output.is_sword() && recipe.output != ItemId::RustyBlade {
1713:             self.flags.crafted_blade = true;
1714:         }
1715:         self.toast(
1716:             &format!("Crafted {}", recipe.name),
1717:             &format!("{} x{}", recipe.output.name(), recipe.out_count),
1718:             recipe.output.color(),
1719:         );
1720:         self.float_text(&format!("+{} {}", recipe.out_count, recipe.output.short()), self.player.center().add(V2::new(0.0, -22.0)), recipe.output.color(), 5.5);
1721:         gfx::sfx(SFX_CRAFT, 0.7);
1722:         self.particles.push(
1723:             Particle::new(self.player.center(), V2::new(0.0, -30.0), 0.6, 2.2, recipe.output.color()).spark(),
1724:         );
1725:         self.save_timer = self.save_timer.min(5.0);
