1762:     pub fn save_game(&mut self) {
1763:         if self.mode == Mode::Attract || self.world.modified.is_empty() && self.stats.play_time < 1.0 {
1764:             // Still save a fresh world once the player has actually started.
1765:         }
1766:         let mut s = String::new();
1767:         s.push_str(SAVE_MAGIC);
1768:         s.push('\n');
1769:         s.push_str(&format!("seed={}\n", self.seed));
1770:         s.push_str(&format!("time={:.4}\n", self.time));
1771:         s.push_str(&format!("day={}\n", self.day));
1772:         s.push_str(&format!(
1773:             "player={:.2},{:.2},{:.2}\n",
1774:             self.player.pos.x, self.player.pos.y, self.player.hp
1775:         ));
1776:         s.push_str(&format!(
1777:             "flags={},{},{},{},{},{}\n",
1778:             self.flags.got_wood as u8,
1779:             self.flags.crafted_bench as u8,
1780:             self.flags.placed_bench as u8,
1781:             self.flags.crafted_blade as u8,
1782:             self.flags.summoned_boss as u8,
1783:             self.flags.boss_defeated as u8
1784:         ));
1785:         s.push_str(&format!(
1786:             "stats={},{},{},{},{:.1}\n",
1787:             self.stats.blocks_mined,
1788:             self.stats.blocks_placed,
1789:             self.stats.enemies_killed,
1790:             self.stats.deaths,
1791:             self.stats.play_time
1792:         ));
1793:         s.push_str("inv=");
1794:         let mut first = true;
1795:         for slot in &self.inventory.slots {
1796:             if let Some(st) = slot {
1797:                 if !first {
1798:                     s.push(';');
1799:                 }
1800:                 first = false;
1801:                 s.push_str(&format!("{}:{}", st.id as u8, st.count));
1802:             }
1803:         }
1804:         s.push('\n');
1805:         s.push_str("mods=");
1806:         for (i, (x, y, t)) in self.world.modified.iter().enumerate() {
1807:             if i > 0 {
1808:                 s.push(';');
1809:             }
1810:             s.push_str(&format!("{x},{y},{t}"));
1811:         }
1812:         s.push('\n');
1813:         gfx::save(s.as_bytes());
1814:         self.saved = Some(SaveData::from_game(self));
1815:     }
