1817:     fn load_from_storage(&mut self) {
1818:         let len = gfx::load_len();
1819:         if len == 0 || len > 4_000_000 {
1820:             return;
1821:         }
1822:         let mut buf = vec![0u8; len as usize];
1823:         let n = gfx::load_read(&mut buf);
1824:         buf.truncate(n as usize);
1825:         let Ok(text) = String::from_utf8(buf) else { return };
1826:         if let Some(save) = SaveData::parse(&text) {
1827:             self.has_save = true;
1828:             self.saved = Some(save);
1829:         }
1830:     }
