1832:     fn apply_save(&mut self, save: SaveData) {
1833:         self.seed = save.seed;
1834:         self.world = World::generate(save.seed);
1835:         for (x, y, t) in save.mods {
1836:             self.world.set_tile(x, y, t);
1837:         }
1838:         self.world.modified.clear();
1839:         self.time = save.time;
1840:         self.day = save.day;
1841:         self.flags = save.flags;
1842:         if self.flags.summoned_boss && !self.flags.boss_defeated {
1843:             // Boss fights are not persisted; let the player summon again.
1844:             self.flags.summoned_boss = false;
1845:         }
1846:         self.stats = save.stats;
1847:         self.inventory = Inventory::new();
1848:         self.inventory.slots = vec![None; INV_SLOTS];
1849:         for (i, (id, count)) in save.inv.into_iter().enumerate() {
1850:             if i < INV_SLOTS {
1851:                 if let Some(id) = ItemId::from_u8(id) {
1852:                     self.inventory.slots[i] = Some(ItemStack { id, count });
1853:                 }
1854:             }
1855:         }
1856:         self.player = Player::new(self.world.spawn);
1857:         self.player.pos = save.player_pos;
1858:         self.player.hp = save.hp.clamp(1.0, self.player.max_hp);
1859:         self.player.respawn = save.player_pos;
1860:         self.boss_defeated = save.flags.boss_defeated;
1861:         self.boss_active = false;
1862:         self.enemies.clear();
1863:         self.drops.clear();
1864:         self.particles.clear();
1865:         self.texts.clear();
1866:         self.mining = None;
1867:         self.center_camera();
1868:         self.was_night = self.is_night();
1869:         gfx::minimap(self.world.minimap.as_ptr(), world::W as u32, world::H as u32);
1870:         self.world.map_dirty = false;
