1940: #[derive(Clone, Debug)]
1941: pub struct SaveData {
1942:     pub seed: u32,
1943:     pub time: f32,
1944:     pub day: u32,
1945:     pub player_pos: V2,
1946:     pub hp: f32,
1947:     pub flags: QuestFlags,
1948:     pub stats: Stats,
1949:     pub inv: Vec<(u8, u32)>,
1950:     pub mods: Vec<(i32, i32, u8)>,
1951: }
1952: 
1953: impl SaveData {
1954:     fn parse(text: &str) -> Option<SaveData> {
1955:         let mut lines = text.lines();
1956:         if lines.next()? != SAVE_MAGIC {
1957:             return None;
1958:         }
1959:         let mut save = SaveData {
1960:             seed: 1337,
1961:             time: 0.3,
1962:             day: 1,
1963:             player_pos: V2::new(0.0, 0.0),
1964:             hp: 100.0,
1965:             flags: QuestFlags::default(),
1966:             stats: Stats::default(),
1967:             inv: Vec::new(),
1968:             mods: Vec::new(),
1969:         };
1970:         let mut has_seed = false;
1971:         let mut has_player = false;
1972:         for line in lines {
1973:             if let Some(v) = line.strip_prefix("seed=") {
1974:                 save.seed = v.parse().ok()?;
1975:                 has_seed = true;
1976:             } else if let Some(v) = line.strip_prefix("time=") {
1977:                 save.time = v.parse().unwrap_or(0.3);
1978:             } else if let Some(v) = line.strip_prefix("day=") {
1979:                 save.day = v.parse().unwrap_or(1);
1980:             } else if let Some(v) = line.strip_prefix("player=") {
1981:                 let p: Vec<&str> = v.split(',').collect();
1982:                 if p.len() >= 3 {
1983:                     save.player_pos = V2::new(p[0].parse().ok()?, p[1].parse().ok()?);
1984:                     save.hp = p[2].parse().unwrap_or(100.0);
1985:                     has_player = true;
1986:                 }
1987:             } else if let Some(v) = line.strip_prefix("flags=") {
1988:                 let f: Vec<u8> = v.split(',').filter_map(|x| x.parse().ok()).collect();
1989:                 if f.len() >= 6 {
1990:                     save.flags = QuestFlags {
1991:                         got_wood: f[0] != 0,
1992:                         crafted_bench: f[1] != 0,
1993:                         placed_bench: f[2] != 0,
1994:                         crafted_blade: f[3] != 0,
1995:                         summoned_boss: f[4] != 0,
1996:                         boss_defeated: f[5] != 0,
1997:                     };
1998:                 }
1999:             } else if let Some(v) = line.strip_prefix("stats=") {
2000:                 let s: Vec<&str> = v.split(',').collect();
2001:                 if s.len() >= 5 {
2002:                     save.stats = Stats {
2003:                         blocks_mined: s[0].parse().unwrap_or(0),
2004:                         blocks_placed: s[1].parse().unwrap_or(0),
