239:     /// Adds items to existing stacks first, then to empty slots. Returns the
240:     /// amount that did not fit.
241:     pub fn add(&mut self, id: ItemId, mut count: u32) -> u32 {
242:         if count == 0 {
243:             return 0;
244:         }
245:         let max = id.max_stack();
246:         if max > 1 {
247:             for slot in self.slots.iter_mut() {
248:                 if count == 0 {
249:                     break;
250:                 }
251:                 if let Some(stack) = slot {
252:                     if stack.id == id && stack.count < max {
253:                         let room = max - stack.count;
254:                         let take = room.min(count);
255:                         stack.count += take;
256:                         count -= take;
257:                     }
258:                 }
259:             }
260:         }
261:         for slot in self.slots.iter_mut() {
262:             if count == 0 {
263:                 break;
264:             }
265:             if slot.is_none() {
266:                 let take = max.min(count);
267:                 *slot = Some(ItemStack { id, count: take });
268:                 count -= take;
269:             }
270:         }
271:         count
272:     }
