291:             if let Some(stack) = slot {
292:                 if stack.id == id {
293:                     let take = stack.count.min(count);
294:                     stack.count -= take;
295:                     count -= take;
296:                     if stack.count == 0 {
297:                         *slot = None;
298:                     }
299:                 }
300:             }
301:         }
302:         true
303:     }
