226:     fn resolve_x(&mut self, world: &World) {
227:         let x0 = (self.pos.x / TILE as f32).floor() as i32;
228:         let x1 = ((self.pos.x + self.width) / TILE as f32).floor() as i32;
229:         let y0 = (self.pos.y / TILE as f32).floor() as i32;
230:         let y1 = ((self.pos.y + self.height - 0.01) / TILE as f32).floor() as i32;
231:         for y in y0..=y1 {
232:             for x in x0..=x1 {
233:                 if world.solid(x, y) {
234:                     if self.vel.x > 0.0 {
235:                         self.pos.x = x as f32 * TILE as f32 - self.width - 0.01;
236:                     } else if self.vel.x < 0.0 {
237:                         self.pos.x = (x + 1) as f32 * TILE as f32 + 0.01;
238:                     }
239:                     self.vel.x = 0.0;
240:                     return;
241:                 }
242:             }
243:         }
244:     }
245: 
246:     fn resolve_y(&mut self, world: &World, prev_bottom: f32) {
247:         let x0 = (self.pos.x / TILE as f32).floor() as i32;
248:         let x1 = ((self.pos.x + self.width) / TILE as f32).floor() as i32;
249:         let y0 = (self.pos.y / TILE as f32).floor() as i32;
250:         let y1 = ((self.pos.y + self.height) / TILE as f32).floor() as i32;
251:         self.on_ground = false;
252:         for y in y0..=y1 {
253:             for x in x0..=x1 {
254:                 let t = world.get(x, y);
255:                 let solid = crate::world::is_solid(t);
256:                 let plat = t == crate::world::PLATFORM;
257:                 if solid || (plat && self.vel.y >= 0.0) {
258:                     if self.vel.y > 0.0 {
259:                         if plat {
260:                             let top = y as f32 * TILE as f32;
261:                             if prev_bottom > top + 1.0 {
262:                                 continue;
263:                             }
264:                         }
265:                         self.pos.y = y as f32 * TILE as f32 - self.height - 0.01;
266:                         self.vel.y = 0.0;
267:                         self.on_ground = true;
268:                         return;
269:                     } else if self.vel.y < 0.0 && solid {
270:                         self.pos.y = (y + 1) as f32 * TILE as f32 + 0.01;
271:                         self.vel.y = 0.0;
272:                         return;
273:                     }
274:                 }
275:             }
276:         }
277:         // Platform check: support only from above.
278:         if self.vel.y >= 0.0 {
279:             let feet_y = self.pos.y + self.height;
280:             let ty = (feet_y / TILE as f32).floor() as i32;
281:             for x in x0..=x1 {
282:                 if world.get(x, ty) == crate::world::PLATFORM {
283:                     let top = ty as f32 * TILE as f32;
284:                     if feet_y >= top - 0.5 && feet_y <= top + 2.5 {
285:                         self.pos.y = top - self.height - 0.01;
286:                         self.vel.y = 0.0;
287:                         self.on_ground = true;
288:                         return;
289:                     }
290:                 }
291:             }
292:         }
293:     }
