374: pub fn generate(seed: u32) -> World {
375:     let mut rng = Rng::new(seed);
376:     let mut tiles = vec![AIR; (W * H) as usize];
377:     let mut walls = vec![WALL_NONE; (W * H) as usize];
378:     let mut surface = vec![(H as f32 * 0.32) as i32; W as usize];
379:     let mut biome = vec![BIOME_FOREST; W as usize];
380: 
381:     let desert_center = W * 68 / 100;
382:     let snow_center = W * 20 / 100;
383: 
384:     // Terrain height and biome assignment.
385:     for x in 0..W {
386:         let base = H as f32 * 0.30;
387:         let broad = (fbm(x as f32 * 0.0052, seed, 4) - 0.5) * 44.0;
388:         let detail = (fbm(x as f32 * 0.021, seed ^ 0x51ed, 3) - 0.5) * 11.0;
389:         let ridge = ((x as f32) * 0.017).sin() * 4.0;
390:         let mut h = (base + broad + detail + ridge).round() as i32;
391:         h = clamp_i(h, 42, (H as f32 * 0.52) as i32);
392: 
393:         let b = if (x - desert_center).abs() < 52 {
394:             BIOME_DESERT
395:         } else if (x - snow_center).abs() < 40 {
396:             BIOME_SNOW
397:         } else if x < 34 || x > W - 34 {
398:             BIOME_SNOW
399:         } else {
400:             BIOME_FOREST
401:         };
402:         biome[x as usize] = b;
403:         surface[x as usize] = h;
404: 
405:         let top_tile = match b {
406:             BIOME_DESERT => SAND,
407:             BIOME_SNOW => SNOW,
408:             _ => GRASS,
409:         };
410:         let filler = match b {
411:             BIOME_DESERT => SAND,
412:             BIOME_SNOW => SNOW,
413:             _ => DIRT,
414:         };
415:         let dirt_depth = 9 + (fbm(x as f32 * 0.13, seed ^ 0x77aa, 2) * 8.0) as i32;
416: 
417:         for y in h..H {
418:             let t = if y == h {
419:                 top_tile
420:             } else if y <= h + dirt_depth {
421:                 if b == BIOME_FOREST && y > h + 4 && hash2(x, y, seed ^ 0x9911) > 0.86 {
422:                     CLAY
423:                 } else {
424:                     filler
425:                 }
426:             } else {
427:                 STONE
428:             };
429:             tiles[World::idx(x, y)] = t;
430:         }
431: 
432:         // Background walls.
433:         for y in h..H {
434:             let depth = y - h;
435:             let w = if depth < 4 {
436:                 WALL_NONE
437:             } else if depth < dirt_depth + 6 {
438:                 WALL_DIRT
439:             } else {
440:                 WALL_STONE
441:             };
442:             walls[World::idx(x, y)] = w;
443:         }
444:     }
