447:     for x in 0..W {
448:         for y in surface[x as usize]..H {
449:             if tiles[World::idx(x, y)] != STONE {
450:                 continue;
451:             }
452:             let n = fbm(x as f32 * 0.055 + y as f32 * 0.033, seed ^ 0xa53, 3);
453:             if n > 0.68 && hash2(x, y, seed ^ 0x441) > 0.45 {
454:                 tiles[World::idx(x, y)] = DIRT;
455:             }
456:         }
457:     }
458: 
