625:         if get_t(tiles.as_slice(), x, y) == AIR
626:             && !is_solid(get_t(tiles.as_slice(), x, y + 1))
627:             && is_solid(get_t(tiles.as_slice(), x, y + 2))
628:             && walls[World::idx(x, y)] != WALL_NONE
629:         {
