642:     for x in 0..W {
643:         let jag = (hash2(x, 0, seed) * 4.0) as i32;
644:         for y in (H - 4 - jag)..H {
645:             if World::in_bounds(x, y) {
646:                 let i = World::idx(x, y);
647:                 tiles[i] = BEDROCK;
648:                 walls[i] = WALL_NONE;
649:             }
650:         }
651:     }
652: 
653:     // Recompute the surface cache after caves/ponds and find a spawn point.
654:     for x in 0..W {
655:         let mut top = H;
656:         for y in 0..H {
657:             let t = tiles[World::idx(x, y)];
658:             if is_solid(t) || t == WATER {
659:                 top = y;
660:                 break;
661:             }
662:         }
663:         surface[x as usize] = top;
664:     }
665: 
666:     let mut spawn_x = W / 2;
667:     let mut best = i32::MAX;
668:     for x in (W / 2 - 60)..(W / 2 + 60) {
669:         let b = biome[x as usize];
670:         let top = surface[x as usize];
671:         if b == BIOME_FOREST && top < H - 20 {
672:             let left = surface[(x - 1) as usize];
673:             let right = surface[(x + 1) as usize];
674:             let flatness = (left - top).abs() + (right - top).abs();
675:             if flatness < best {
676:                 best = flatness;
677:                 spawn_x = x;
678:             }
679:         }
680:     }
681:     if best == i32::MAX {
682:         spawn_x = W / 2;
683:     }
684:     let ground_y = surface[spawn_x as usize];
685:     let mut spawn = V2::new(spawn_x as f32 * TILE as f32 + TILE as f32 * 0.5, (ground_y as f32 - 2.2) * TILE as f32);
