687:     // Ensure there is a solid pad under the spawn.
688:     for yy in ground_y..(ground_y + 3).min(H) {
689:         let i = World::idx(spawn_x, yy);
690:         if !is_solid(tiles[i]) {
691:             tiles[i] = DIRT;
692:         }
693:     }
694:     if get_t(tiles.as_slice(), spawn_x, ground_y - 1) != AIR {
695:         let i = World::idx(spawn_x, ground_y - 1);
696:         tiles[i] = AIR;
697:     }
698:     spawn.y = (ground_y as f32 - 2.0) * TILE as f32;
699: 
700:     let mut sky_top = vec![H; W as usize];
701:     for x in 0..W {
702:         let mut top = H;
703:         for y in 0..H {
704:             let t = tiles[World::idx(x, y)];
705:             if is_solid(t) || t == WATER {
706:                 top = y;
707:                 break;
708:             }
709:         }
710:         sky_top[x as usize] = top;
711:         surface[x as usize] = top;
712:     }
