730: fn get_t(tiles: &[u8], x: i32, y: i32) -> u8 {
731:     if World::in_bounds(x, y) {
732:         tiles[World::idx(x, y)]
733:     } else {
734:         AIR
735:     }
736: }
737: 
738: fn set_t(tiles: &mut [u8], x: i32, y: i32, t: u8) {
739:     if World::in_bounds(x, y) {
740:         tiles[World::idx(x, y)] = t;
741:     }
742: }
743: 
744: fn carve_circle(tiles: &mut [u8], walls: &mut [u8], cx: f32, cy: f32, r: f32, seed: u32) {
745:     let x0 = (cx - r - 1.0) as i32;
746:     let x1 = (cx + r + 1.0) as i32;
747:     let y0 = (cy - r - 1.0) as i32;
748:     let y1 = (cy + r + 1.0) as i32;
749:     for y in y0..=y1 {
750:         for x in x0..=x1 {
751:             if !World::in_bounds(x, y) {
752:                 continue;
753:             }
754:             let d = ((x as f32 - cx).powi(2) + (y as f32 - cy).powi(2)).sqrt();
755:             if d <= r {
756:                 let i = World::idx(x, y);
757:                 if is_solid(tiles[i]) {
758:                     if walls[i] == WALL_NONE {
759:                         walls[i] = if y > (H / 2) { WALL_STONE } else { WALL_DIRT };
760:                     }
761:                     tiles[i] = AIR;
762:                 } else if tiles[i] == AIR {
763:                     // Keep background walls behind natural caverns.
764:                     if walls[i] == WALL_NONE && y > 8 {
765:                         walls[i] = if y > (H / 2) { WALL_STONE } else { WALL_DIRT };
766:                     }
767:                 }
768:             }
769:             // Rough the rim a little.
770:             if d > r && d <= r + 0.75 && hash2(x, y, seed) > 0.82 {
771:                 let i = World::idx(x, y);
772:                 if is_solid(tiles[i]) {
773:                     tiles[i] = AIR;
774:                 }
775:             }
776:         }
777:     }
778: }
779: 
780: fn grow_tree(tiles: &mut [u8], walls: &mut [u8], x: i32, ground: i32, seed: u32, rng: &mut Rng, biome: u8) {
781:     let height = rng.range_i(5, 11);
782:     let pine = biome == BIOME_SNOW;
783:     for i in 1..=height {
784:         let y = ground - i;
785:         if !World::in_bounds(x, y) {
786:             return;
787:         }
788:         set_t(tiles, x, y, WOOD);
789:     }
790:     let top = ground - height;
791:     if pine {
792:         for layer in 0..4 {
793:             let y = top - layer;
794:             let r = 2 + (3 - layer) as i32;
795:             for dx in -r..=r {
796:                 for dy in -1i32..=1 {
797:                     if dx.abs() + dy.abs() * 2 <= r + 1 {
798:                         let tx = x + dx;
799:                         let ty = y + dy;
800:                         if World::in_bounds(tx, ty) && get_t(tiles, tx, ty) == AIR {
801:                             set_t(tiles, tx, ty, LEAVES);
802:                         }
803:                     }
804:                 }
805:             }
806:         }
807:         set_t(tiles, x, top - 4, LEAVES);
808:         set_t(tiles, x, top - 5, LEAVES);
809:     } else {
810:         let r = rng.range_i(2, 4);
811:         for dy in -r..=r {
812:             for dx in -r..=r {
813:                 let d = (dx * dx + dy * dy) as f32;
814:                 if d <= (r * r) as f32 + 1.0 && hash2(x + dx, top + dy, seed ^ 0x77) > 0.18 {
815:                     let tx = x + dx;
816:                     let ty = top + dy - 1;
817:                     if World::in_bounds(tx, ty) && get_t(tiles, tx, ty) == AIR {
818:                         set_t(tiles, tx, ty, LEAVES);
819:                     }
820:                 }
821:             }
822:         }
823:         // A couple of branches.
824:         for side in [-1, 1] {
825:             if rng.chance(0.7) {
826:                 let by = ground - height / 2;
827:                 for step in 1..=2 {
828:                     set_t(tiles, x + side * step, by - step + 1, WOOD);
829:                 }
830:             }
831:         }
832:     }
833:     // Roots / dirt collar.
834:     for dx in -1..=1 {
835:         let wx = x + dx;
836:         let wy = ground;
837:         if World::in_bounds(wx, wy) && get_t(tiles, wx, wy) == AIR {
838:             // no-op, keeps trunks on the ground
839:         }
840:     }
841:     let _ = walls;
842: }
843: 
844: fn build_cabin(tiles: &mut [u8], walls: &mut [u8], cx: i32, cy: i32, rng: &mut Rng) {
845:     let w = rng.range_i(7, 10);
846:     let h = rng.range_i(5, 6);
847:     let x0 = cx - w / 2;
848:     let y0 = cy - h;
849:     // Clear and build walls.
850:     for y in y0..=(cy + 1) {
851:         for x in x0..=(x0 + w) {
852:             if !World::in_bounds(x, y) {
853:                 continue;
854:             }
855:             let i = World::idx(x, y);
856:             tiles[i] = AIR;
857:             walls[i] = WALL_WOOD;
858:         }
859:     }
860:     // Floor.
861:     for x in x0..=(x0 + w) {
862:         let y = cy + 1;
863:         if World::in_bounds(x, y) {
864:             let i = World::idx(x, y);
865:             if !is_solid(tiles[i]) {
866:                 tiles[i] = WOOD;
867:             }
868:         }
869:     }
870:     // Side pillars.
871:     for y in y0..=cy {
872:         for x in [x0, x0 + w] {
873:             if World::in_bounds(x, y) {
874:                 let i = World::idx(x, y);
875:                 tiles[i] = WOOD;
876:             }
877:         }
878:     }
879:     // Roof.
880:     for x in x0..=(x0 + w) {
881:         if World::in_bounds(x, y0 - 1) {
882:             let i = World::idx(x, y0 - 1);
883:             tiles[i] = WOOD;
884:         }
885:     }
886:     // Doorway gaps.
887:     for y in (cy - 2)..=cy {
888:         let i = World::idx(x0, y);
889:         if y >= cy - 1 {
890:             let idx = World::idx(x0, y);
891:             if World::in_bounds(x0, y) {
892:                 tiles[idx] = AIR;
893:                 let _ = i;
894:             }
895:         }
896:     }
897:     // Furniture.
898:     if World::in_bounds(x0 + 2, cy) {
899:         let i = World::idx(x0 + 2, cy);
900:         if tiles[i] == AIR {
901:             tiles[i] = BENCH;
902:         }
903:     }
904:     if World::in_bounds(x0 + w - 2, cy - 3) {
905:         let i = World::idx(x0 + w - 2, cy - 3);
906:         if tiles[i] == AIR {
907:             tiles[i] = TORCH;
908:         }
909:     }
910:     let _ = rng;
911: }
