    if i<100: continue
    typ=m.get('type')
    if typ=='assistant':
        for c in m.get('content',[]):
            t=c.get('type')
            if t=='text':
                print(f"[{i}] TEXT: {textwrap.shorten(c['text'].replace(chr(10),' '), 500)}")
            elif t=='tool':
                inp=c.get('state',{}).get('input',{})
                print(f"[{i}] TOOL {c.get('name')}: {json.dumps(inp)[:500]}")
                cont=c.get('state',{}).get('content',[])
                txt=' '.join(x.get('text','') for x in cont if isinstance(x,dict))
                if txt: print(f"     -> {textwrap.shorten(txt.replace(chr(10),' '), 500)}")
    elif typ=='user':
        print(f"[{i}] USER: {m.get('text','')[:300]}")
