159:     let w = (game.view.x - 24.0 * s).min(430.0 * s).max(250.0);
160:     let h = (game.view.y - 24.0 * s).min(330.0 * s).max(250.0);
161:     let panel = Rect::new((game.view.x - w) * 0.5, (game.view.y - h) * 0.5, w, h);
162:     let bw = w - 30.0 * s;
163:     let bh = 26.0 * s;
164:     let bx = panel.x + 15.0 * s;
165:     let by = panel.y + h - 15.0 * s - bh * 4.0 - 7.0 * s * 3.0;
166:     PauseLayout {
167:         panel,
168:         resume: Rect::new(bx, by, bw, bh),
169:         help: Rect::new(bx, by + (bh + 7.0 * s), bw, bh),
170:         mute: Rect::new(bx, by + (bh + 7.0 * s) * 2.0, bw, bh),
171:         quit: Rect::new(bx, by + (bh + 7.0 * s) * 3.0, bw, bh),
172:         s,
173:     }
174: }
