278: fn draw_hearts(game: &Game, s: f32) {
279:     let p = &game.player;
280:     let x0 = 12.0 * s;
281:     let y = 18.0 * s;
282:     let step = 12.3 * s;
283:     let hp = p.hp.max(0.0);
284:     for i in 0..10 {
285:         let frac = clamp((hp - i as f32 * 10.0) / 10.0, 0.0, 1.0);
286:         let x = x0 + i as f32 * step;
287:         let col = if frac > 0.0 {
288:             if p.hp < 30.0 {
289:                 let pulse = 0.75 + 0.25 * (game.title_phase * 8.0).sin();
290:                 mix(rgb(210, 54, 68), rgb(255, 120, 120), pulse)
291:             } else {
292:                 rgb(222, 64, 78)
293:             }
294:         } else {
295:             rgb(44, 40, 50)
296:         };
297:         draw_heart(x, y, 9.0 * s, col, frac > 0.0);
298:         if frac > 0.0 && frac < 1.0 {
299:             // Partial heart is approximated by a smaller filled heart.
300:             draw_heart(x, y, 9.0 * s * (0.55 + frac * 0.45), mix(rgb(222, 64, 78), rgb(255, 150, 150), 0.4), true);
301:         }
302:     }
303:     let hp_text = format!("{}/{}", p.hp.ceil() as i32, p.max_hp as i32);
304:     gfx::text(&hp_text, x0 + 10.0 * step + 4.0 * s, y + 3.5 * s, 6.0 * s, rgba(240, 228, 220, 220), 0, 700);
305:     let hurt = game.hurt_vignette;
306:     if hurt > 0.05 {
307:         gfx::rect(0.0, 0.0, game.view.x, game.view.y, rgba(180, 20, 30, (hurt * 34.0) as u8));
308:     }
309: }
