311: fn draw_heart(x: f32, y: f32, size: f32, color: u32, filled: bool) {
312:     let c = if filled { color } else { rgba(20, 18, 26, 210) };
313:     gfx::circle(x + size * 0.28, y + size * 0.3, size * 0.28, c);
314:     gfx::circle(x + size * 0.72, y + size * 0.3, size * 0.28, c);
315:     gfx::tri(x - size * 0.02, y + size * 0.38, x + size * 0.5, y + size, x + size * 1.02, y + size * 0.38, c);
316:     if filled {
317:         gfx::circle(x + size * 0.24, y + size * 0.24, size * 0.1, rgba(255, 190, 190, 160));
318:     }
319: }
