335: fn draw_clock_depth(game: &Game, s: f32) {
336:     let time = game.time;
337:     let hours = (5.0 + time * 24.0) % 24.0;
338:     let hh = hours.floor() as i32;
339:     let mm = ((hours - hours.floor()) * 60.0) as i32;
340:     let label = format!("Day {}  {:02}:{:02}", game.day, hh, mm);
341:     let w = 92.0 * s;
342:     let x = game.view.x - w - 10.0 * s;
343:     let y = if game.touch_mode { 90.0 * s } else { 62.0 * s };
344:     gfx::rect(x, y, w, 17.0 * s, rgba(14, 18, 28, 185));
345:     gfx::rect(x, y, 2.0 * s, 17.0 * s, rgb(120, 164, 188));
346:     let icon_col = if game.is_night() { rgb(190, 208, 255) } else { rgb(255, 214, 110) };
347:     gfx::circle(x + 10.0 * s, y + 8.5 * s, 3.0 * s, icon_col);
348:     if game.is_night() {
349:         gfx::circle(x + 12.0 * s, y + 7.5 * s, 2.4 * s, rgba(14, 18, 28, 255));
350:     }
351:     gfx::text(&label, x + 18.0 * s, y + 8.7 * s, 5.8 * s, rgb(232, 232, 226), 0, 700);
352: 
353:     let surface = game.world.surface_px(game.player.pos.x as i32);
354:     let depth = ((game.player.feet().y - surface) / TILE as f32 * 2.0).round() as i32;
355:     let depth_label = if depth >= 0 {
356:         format!("Depth {} ft", depth)
357:     } else {
358:         format!("{} ft above", -depth)
359:     };
360:     let dx = game.view.x - 10.0 * s;
361:     let dy = game.view.y * 0.55;
362:     text_shadow(&depth_label, dx, dy, 6.0 * s, rgba(214, 218, 224, 210), 2, 600);
363: }
