365: fn draw_hotbar(game: &Game, s: f32) {
366:     let layout = hotbar_layout(game);
367:     let hover = layout.slot_at(game.mouse_screen);
368:     for (i, r) in layout.slots.iter().enumerate() {
369:         let selected = i == game.inventory.selected;
370:         let fill = if selected {
371:             rgba(58, 66, 78, 235)
372:         } else {
373:             rgba(18, 22, 32, 205)
374:         };
375:         gfx::rect(r.x, r.y, r.w, r.h, fill);
376:         let border = if selected {
377:             rgb(238, 200, 102)
378:         } else if hover == Some(i) {
379:             rgb(130, 160, 172)
380:         } else {
381:             rgba(92, 104, 118, 180)
382:         };
383:         let bw = if selected { 1.8 * s } else { 1.0 * s };
384:         gfx::rect(r.x, r.y, r.w, bw, border);
385:         gfx::rect(r.x, r.y + r.h - bw, r.w, bw, border);
386:         gfx::rect(r.x, r.y, bw, r.h, border);
387:         gfx::rect(r.x + r.w - bw, r.y, bw, r.h, border);
388:         if selected {
389:             gfx::rect(r.x - 2.0 * s, r.y - 2.0 * s, r.w + 4.0 * s, 2.0 * s, rgb(238, 200, 102));
390:         }
391:         if let Some(st) = game.inventory.slots[i] {
392:             draw_item_icon(st.id, r.x + r.w * 0.5, r.y + r.h * 0.48, r.w * 0.62, 240);
393:             if st.count > 1 {
394:                 gfx::text(&st.count.to_string(), r.x + r.w - 3.0 * s, r.y + r.h - 6.0 * s, 5.4 * s, rgb(246, 244, 236), 2, 800);
395:             }
396:         } else {
397:             gfx::text("-", r.x + r.w * 0.5, r.y + r.h * 0.5, 6.0 * s, rgba(120, 128, 140, 110), 1, 400);
398:         }
399:         gfx::text(&format!("{}", if i == 9 { 0 } else { i + 1 }), r.x + 3.0 * s, r.y + 5.5 * s, 4.6 * s, rgba(220, 220, 220, 120), 0, 700);
400:     }
401:     // Selected item name.
402:     if let Some(st) = game.inventory.selected_stack() {
403:         let y = layout.y - 13.0 * s;
404:         let name = st.id.name();
405:         let w = gfx::text_width(name, 6.5 * s, 700) + 18.0 * s;
406:         let x = game.view.x * 0.5 - w * 0.5;
407:         gfx::rect(x, y - 7.0 * s, w, 14.0 * s, rgba(12, 16, 24, 200));
408:         gfx::rect(x, y - 7.0 * s, w, 1.0, alpha(st.id.color(), 200));
409:         gfx::text(name, game.view.x * 0.5, y, 6.5 * s, rgb(240, 238, 228), 1, 700);
410:     }
411: }
