413: fn draw_boss_bar(game: &Game, s: f32) {
414:     if !game.boss_active {
415:         return;
416:     }
417:     let Some(boss) = game.enemies.iter().find(|e| e.kind.is_boss() && !e.dead) else { return };
418:     let w = (game.view.x * 0.56).min(390.0 * s);
419:     let h = 8.0 * s;
420:     let x = (game.view.x - w) * 0.5;
421:     let y = if game.view.x < 480.0 { 76.0 * s } else { 18.0 * s };
422:     text_shadow("THE SLIME KING", game.view.x * 0.5, y - 7.0 * s, 7.0 * s, rgb(198, 246, 214), 1, 800);
423:     gfx::rect(x - 1.0, y - 1.0, w + 2.0, h + 2.0, rgba(8, 12, 18, 220));
424:     gfx::rect(x, y, w, h, rgba(44, 34, 42, 220));
425:     let f = (boss.hp / boss.max_hp).clamp(0.0, 1.0);
426:     gfx::rect(x, y, w * f, h, mix(rgb(184, 54, 62), rgb(94, 212, 144), f));
427:     gfx::rect(x, y, w * f, h * 0.35, rgba(255, 255, 255, 45));
428:     for i in 1..10 {
429:         gfx::rect(x + w * i as f32 / 10.0, y, 1.0, h, rgba(10, 12, 18, 90));
430:     }
431:     draw_item_icon(ItemId::Crown, x - 9.0 * s, y + h * 0.5, 11.0 * s, 230);
432: }
