434: fn draw_toasts(game: &Game, s: f32) {
435:     let layout = hotbar_layout(game);
436:     let mut y = layout.y - 26.0 * s;
437:     for t in game.toasts.iter().rev().take(3) {
438:         let a = ((t.life.min(0.5) / 0.5) * 255.0).clamp(0.0, 255.0) as u8;
439:         let x = 12.0 * s;
440:         let w = 210.0 * s;
441:         let h = 25.0 * s;
442:         gfx::rect(x, y - h, w, h, rgba(14, 18, 26, (a as f32 * 0.85) as u8));
443:         gfx::rect(x, y - h, 3.0 * s, h, alpha(t.color, a));
444:         gfx::text(&t.text, x + 8.0 * s, y - h + 9.0 * s, 6.2 * s, alpha(t.color, a), 0, 800);
445:         gfx::text(&t.sub, x + 8.0 * s, y - h + 18.0 * s, 4.9 * s, rgba(190, 196, 204, a), 0, 500);
446:         y -= h + 4.0 * s;
447:     }
448: }
