450: fn draw_banner(game: &Game, s: f32) {
451:     let Some(b) = &game.banner else { return };
452:     let f = (b.life / b.max_life).clamp(0.0, 1.0);
453:     let fade = ((1.0 - f) * 5.0).min(1.0).min((f * 5.0).min(1.0));
454:     let a = (fade * 255.0) as u8;
455:     let y = game.view.y * 0.24;
456:     let w = (game.view.x * 0.72).min(520.0 * s);
457:     gfx::rect((game.view.x - w) * 0.5, y - 22.0 * s, w, 2.0 * s, rgba(240, 210, 120, (a as f32 * 0.5) as u8));
458:     gfx::rect((game.view.x - w) * 0.5, y + 22.0 * s, w, 1.0 * s, rgba(240, 210, 120, (a as f32 * 0.35) as u8));
459:     text_shadow(&b.text, game.view.x * 0.5, y - 6.0 * s, 19.0 * s, alpha(b.color, a), 1, 900);
460:     gfx::text(&b.sub, game.view.x * 0.5, y + 13.0 * s, 6.5 * s, rgba(232, 226, 210, a), 1, 600);
461: }
