467: fn draw_inventory(game: &Game) {
468:     let l = inventory_layout(game);
469:     let s = l.s;
470:     gfx::rect(0.0, 0.0, game.view.x, game.view.y, rgba(4, 6, 12, 150));
471:     shadow_panel(l.panel, rgba(20, 24, 34, 246), rgb(118, 148, 158));
472:     gfx::text("INVENTORY", l.panel.x + 12.0 * s, l.panel.y + 15.0 * s, 10.0 * s, rgb(240, 236, 222), 0, 900);
473:     gfx::text("& CRAFTING", l.panel.x + 12.0 * s + gfx::text_width("INVENTORY ", 10.0 * s, 900), l.panel.y + 15.0 * s, 10.0 * s, rgb(202, 172, 100), 0, 900);
474: 
475:     // Close button.
476:     let cx = l.close.center();
477:     let close_hover = l.close.contains(game.mouse_screen);
478:     gfx::rect(l.close.x, l.close.y, l.close.w, l.close.h, if close_hover { rgba(160, 70, 70, 230) } else { rgba(48, 44, 52, 220) });
479:     gfx::line(cx.x - 3.0 * s, cx.y - 3.0 * s, cx.x + 3.0 * s, cx.y + 3.0 * s, 1.6 * s, rgb(230, 220, 210));
480:     gfx::line(cx.x + 3.0 * s, cx.y - 3.0 * s, cx.x - 3.0 * s, cx.y + 3.0 * s, 1.6 * s, rgb(230, 220, 210));
481: 
482:     let bench = game.world.bench_near(game.player.center().x, game.player.center().y, 6);
483:     let bench_text = if bench { "WORKBENCH NEARBY" } else { "WORKBENCH REQUIRED FOR ADVANCED ITEMS" };
484:     gfx::text(bench_text, l.panel.x + l.panel.w - 36.0 * s, l.panel.y + 17.0 * s, 4.8 * s, if bench { rgb(144, 214, 160) } else { rgba(210, 176, 108, 220) }, 2, 700);
485: 
486:     for (i, r) in l.slots.iter().enumerate() {
487:         let selected = i == game.inventory.selected;
488:         let hover = game.hover_inv_slot == Some(i);
489:         let fill = if selected { rgba(60, 68, 82, 240) } else if i < HOTBAR { rgba(28, 34, 46, 230) } else { rgba(22, 26, 36, 220) };
490:         gfx::rect(r.x, r.y, r.w, r.h, fill);
491:         let border = if selected { rgb(236, 198, 100) } else if hover { rgb(144, 176, 188) } else { rgba(82, 94, 108, 170) };
492:         stroke_rect(*r, if selected { 1.6 * s } else { 1.0 }, border);
493:         if let Some(st) = game.inventory.slots[i] {
494:             draw_item_icon(st.id, r.x + r.w * 0.5, r.y + r.h * 0.47, r.w * 0.62, 245);
495:             if st.count > 1 {
496:                 gfx::text(&st.count.to_string(), r.x + r.w - 2.5 * s, r.y + r.h - 5.5 * s, 4.8 * s, rgb(248, 246, 236), 2, 800);
497:             }
498:         }
499:         if i < HOTBAR {
500:             gfx::text(&format!("{}", if i == 9 { 0 } else { i + 1 }), r.x + 2.5 * s, r.y + 5.0 * s, 4.2 * s, rgba(210, 210, 210, 110), 0, 700);
501:         } else if hover {
502:             gfx::text("swap", r.x + r.w * 0.5, r.y + r.h - 5.0 * s, 3.8 * s, rgba(170, 200, 210, 200), 1, 600);
503:         }
504:     }
505: 
506:     // Recipes.
507:     for (i, recipe) in RECIPES.iter().enumerate() {
508:         let Some(r) = l.recipes.get(i) else { continue };
509:         let hover = game.hover_recipe == Some(i);
510:         let mut can = true;
511:         for inp in recipe.inputs.iter().flatten() {
512:             if game.inventory.count(inp.0) < inp.1 {
513:                 can = false;
514:             }
515:         }
516:         if recipe.bench && !bench {
517:             can = false;
518:         }
519:         let fill = if hover && can {
520:             rgba(48, 70, 66, 240)
521:         } else if hover {
522:             rgba(56, 46, 44, 230)
523:         } else {
524:             rgba(24, 28, 38, 215)
525:         };
526:         gfx::rect(r.x, r.y, r.w, r.h, fill);
527:         stroke_rect(*r, 1.0, if hover { rgba(150, 184, 176, 220) } else { rgba(70, 80, 94, 150) });
528:         draw_item_icon(recipe.output, r.x + 9.0 * s, r.y + r.h * 0.5, 11.0 * s, if can { 240 } else { 90 });
529:         let name_col = if can { rgb(238, 236, 224) } else { rgba(166, 168, 172, 220) };
530:         gfx::text(recipe.name, r.x + 18.0 * s, r.y + 7.0 * s, 5.8 * s, name_col, 0, 700);
531:         gfx::text(&format!("x{}", recipe.out_count), r.x + r.w - 5.0 * s, r.y + 7.0 * s, 5.0 * s, rgba(210, 190, 130, 210), 2, 700);
532:         // Ingredient string.
533:         let mut ingredients = Vec::new();
534:         for inp in recipe.inputs.iter().flatten() {
535:             let have = game.inventory.count(inp.0);
536:             ingredients.push(format!("{} {}/{}", inp.0.short(), have, inp.1));
537:         }
538:         if recipe.bench {
