72: fn sky_palette(time: f32) -> (u32, u32, u32) {
73:     let keys: [(f32, u32, u32, u32); 7] = [
74:         (0.00, 0x22305C, 0xD88068, 0x8FA0C8),
75:         (0.10, 0x3C86C8, 0xB5E2F8, 0x9CC8E8),
76:         (0.28, 0x4B9CE0, 0xCDEEFF, 0xAFD8F0),
77:         (0.52, 0x4E92D8, 0xD6EEFF, 0xAED2EA),
78:         (0.60, 0x3A2A68, 0xF08A5A, 0xC87870),
79:         (0.68, 0x080D24, 0x1B2A52, 0x26365E),
80:         (0.95, 0x080D24, 0x1B2A52, 0x26365E),
81:     ];
82:     let mut top = keys[0].1;
83:     let mut hor = keys[0].2;
84:     let mut haze = keys[0].3;
85:     for i in 0..keys.len() - 1 {
86:         let a = keys[i];
87:         let b = keys[i + 1];
88:         if time >= a.0 && time <= b.0 {
89:             let k = ((time - a.0) / (b.0 - a.0)).max(0.0);
90:             let k = k * k * (3.0 - 2.0 * k);
91:             top = mix(a.1, b.1, k);
92:             hor = mix(a.2, b.2, k);
93:             haze = mix(a.3, b.3, k);
94:             break;
95:         }
96:     }
97:     (top, hor, haze)
98: }
