100: fn draw_sky(game: &Game, v: &View) {
101:     let (top, horizon, haze) = sky_palette(game.time);
102:     gfx::gradient(0.0, 0.0, v.w, v.h, top, horizon, true);
103:     let light = game.sky_light();
104: 
105:     // Stars.
106:     let star_alpha = ((1.0 - light) * 255.0).clamp(0.0, 255.0) as u8;
107:     if star_alpha > 8 {
108:         for i in 0..90 {
109:             let sx = (hash2(i, 4, v.seed) * v.w + v.t * (0.4 + (i % 5) as f32 * 0.2)) % v.w;
110:             let sy = hash2(i, 7, v.seed) * v.h * 0.6;
111:             let tw = 0.55 + 0.45 * (v.t * 1.7 + i as f32 * 1.13).sin();
112:             let a = (star_alpha as f32 * tw) as u8;
113:             let size = if i % 9 == 0 { 1.6 } else { 1.0 };
114:             gfx::rect(sx, sy, size, size, rgba(220, 230, 255, a));
115:             if i % 17 == 0 {
116:                 gfx::glow(sx + 0.5, sy + 0.5, 5.0, rgba(160, 190, 255, (a as f32 * 0.25) as u8));
117:             }
118:         }
119:     }
120: 
121:     // Sun.
122:     if game.time > 0.01 && game.time < 0.61 {
123:         let t = ((game.time - 0.01) / 0.60).clamp(0.0, 1.0);
124:         let x = v.w * (0.06 + t * 0.88);
125:         let y = v.h * 0.62 - (t * std::f32::consts::PI).sin() * v.h * 0.54;
126:         gfx::glow(x, y, 70.0, rgba(255, 228, 150, 70));
127:         gfx::circle(x, y, 13.0, rgb(255, 238, 176));
128:         gfx::circle(x, y, 9.0, rgb(255, 250, 220));
129:     }
130:     // Moon.
131:     if game.time > 0.61 || game.time < 0.02 {
132:         let t = if game.time > 0.61 {
133:             ((game.time - 0.61) / 0.39).clamp(0.0, 1.0)
134:         } else {
135:             ((game.time + 0.39) / 0.41).clamp(0.0, 1.0)
136:         };
137:         let x = v.w * (0.06 + t * 0.88);
138:         let y = v.h * 0.62 - (t * std::f32::consts::PI).sin() * v.h * 0.54;
139:         gfx::glow(x, y, 55.0, rgba(150, 180, 255, 45));
140:         gfx::circle(x, y, 11.0, rgb(224, 232, 250));
141:         gfx::circle(x - 3.0, y - 2.0, 2.0, rgba(172, 186, 220, 180));
142:         gfx::circle(x + 4.0, y + 3.0, 1.4, rgba(180, 194, 228, 160));
143:         gfx::circle(x + 2.0, y - 5.0, 1.2, rgba(180, 194, 228, 140));
144:     }
145: 
146:     // Stars/haze glow at horizon.
147:     gfx::rect(0.0, v.h * 0.58, v.w, v.h * 0.42, alpha(haze, 22));
148: 
149:     // Clouds.
150:     let cloud_tint = mix(rgb(255, 255, 255), rgb(90, 110, 160), clamp((0.55 - game.sky_light()).max(0.0) * 1.8, 0.0, 0.85));
151:     for i in 0..8 {
152:         let speed = 2.5 + (i % 3) as f32 * 1.8;
153:         let base = hash2(i, 21, v.seed) * (v.w + 400.0) - 200.0;
154:         let x = ((base + v.t * speed) % (v.w + 400.0) + (v.w + 400.0)) % (v.w + 400.0) - 200.0;
155:         let y = v.h * (0.06 + hash2(i, 22, v.seed) * 0.24);
156:         let s = 0.75 + hash2(i, 23, v.seed) * 0.9;
157:         let a = (120.0 * (0.45 + 0.55 * game.sky_light())) as u8;
158:         cloud(x, y, s, alpha(cloud_tint, a));
159:     }
160: }
