170: fn draw_parallax(game: &Game, v: &View) {
171:     let center_col = clamp_i(((v.x + v.w * 0.5) / TILE as f32) as i32, 0, world::W - 1);
172:     let horizon_world = game.world.surface_px(center_col);
173:     let horizon = horizon_world - v.y;
174:     if horizon < -v.h || horizon > v.h * 1.6 {
175:         return;
176:     }
177:     let (_, _, haze) = sky_palette(game.time);
178:     let layer_colors = [
179:         mix(haze, rgb(44, 62, 92), 0.45),
180:         mix(haze, rgb(38, 78, 66), 0.62),
181:         mix(haze, rgb(26, 58, 48), 0.78),
182:     ];
183:     let specs = [(0.06, 150.0, 0.55), (0.12, 115.0, 0.72), (0.20, 82.0, 0.9)];
184:     for (li, (par, amp, darkness)) in specs.iter().enumerate() {
185:         let base = horizon + 42.0 - li as f32 * 4.0;
186:         let off = v.x * par;
187:         let mut pts: Vec<V2> = Vec::new();
188:         pts.push(V2::new(-40.0, v.h + 20.0));
189:         let mut sx = -40.0;
190:         while sx <= v.w + 40.0 {
191:             let wx = sx + off;
192:             let n = fbm(wx * 0.0042 + li as f32 * 11.0, v.seed ^ (li as u32 * 0x1234), 3);
193:             let hill = (n * 0.72 + 0.28) * amp;
194:             let y = base - hill;
195:             pts.push(V2::new(sx, y));
196:             sx += 38.0;
197:         }
198:         pts.push(V2::new(v.w + 40.0, v.h + 20.0));
199:         let c = mix(layer_colors[li], rgb(8, 12, 22), 1.0 - darkness);
200:         gfx::poly(&pts, c);
201:     }
202: }
