208: fn draw_world(game: &Game, v: &View) {
209:     let w = &game.world;
210:     let x0 = ((v.x / TILE as f32).floor() as i32 - 1).max(0);
211:     let y0 = ((v.y / TILE as f32).floor() as i32 - 1).max(0);
212:     let x1 = (((v.x + v.w) / TILE as f32).ceil() as i32 + 1).min(world::W - 1);
213:     let y1 = (((v.y + v.h) / TILE as f32).ceil() as i32 + 1).min(world::H - 1);
214: 
215:     // Solid underground backdrop to cover the sky when deep.
216:     let surf_y = w.surface_px(clamp_i(((v.x + v.w * 0.5) / TILE as f32) as i32, 0, world::W - 1));
217:     if v.y + v.h > surf_y + 64.0 {
218:         let dark_top = (surf_y + 64.0 - v.y).max(0.0);
219:         gfx::rect(0.0, dark_top, v.w, v.h - dark_top, rgb(10, 12, 20));
220:     }
221: 
222:     // Background walls.
223:     for ty in y0..=y1 {
224:         for tx in x0..=x1 {
225:             let wall = w.get_wall(tx, ty);
226:             if wall == world::WALL_NONE {
227:                 continue;
228:             }
229:             let t = w.get(tx, ty);
230:             if world::is_solid(t) {
231:                 continue;
232:             }
233:             draw_wall(v, tx, ty, wall);
234:         }
235:     }
236: 
237:     // Tiles.
238:     for ty in y0..=y1 {
239:         for tx in x0..=x1 {
240:             let t = w.get(tx, ty);
241:             if t == world::AIR {
242:                 continue;
243:             }
244:             let sx = v.tile_x(tx).floor();
245:             let sy = v.tile_y(ty).floor();
246:             match t {
247:                 world::WATER => draw_water(v, tx, ty, sx, sy, w),
248:                 world::TORCH => draw_torch(v, tx, ty, sx, sy),
249:                 world::PLATFORM => draw_platform(sx, sy),
250:                 world::BENCH => draw_bench(sx, sy),
251:                 world::MUSHROOM => draw_mushroom(sx, sy),
252:                 _ => draw_block(v, tx, ty, t, sx, sy, w),
253:             }
254:         }
255:     }
256: 
257:     // Surface decorations (grass blades, flowers, snow sparkle).
258:     for ty in y0..=y1 {
259:         for tx in x0..=x1 {
260:             let t = w.get(tx, ty);
261:             if t != world::GRASS && t != world::SNOW && t != world::SAND {
262:                 continue;
263:             }
264:             if w.get(tx, ty - 1) != world::AIR {
265:                 continue;
266:             }
267:             let sx = v.tile_x(tx);
268:             let sy = v.tile_y(ty);
269:             let h = hash2(tx, ty, v.seed);
270:             if t == world::GRASS {
271:                 let n = if h > 0.6 { 3 } else if h > 0.3 { 2 } else { 1 };
272:                 for k in 0..n {
273:                     let ox = 3.0 + hash2(tx + k * 7, ty, v.seed) * 10.0;
274:                     let hh = 3.0 + hash2(tx, ty + k * 3, v.seed) * 5.0;
275:                     let sway = (v.t * 1.4 + tx as f32 + k as f32).sin() * 1.2;
276:                     gfx::line(sx + ox, sy + 1.0, sx + ox + sway, sy - hh, 1.1, rgb(66, 132, 54));
277:                 }
278:                 if h > 0.87 {
279:                     let col = if h > 0.94 { rgb(250, 214, 96) } else { rgb(228, 120, 146) };
280:                     gfx::rect(sx + 5.0, sy - 5.0, 2.0, 3.0, col);
281:                     gfx::rect(sx + 4.0, sy - 3.0, 1.5, 3.0, rgb(70, 140, 60));
282:                 }
283:             } else if t == world::SNOW && h > 0.72 {
284:                 let a = (160.0 + (v.t * 3.0 + tx as f32).sin() * 50.0) as u8;
285:                 gfx::rect(sx + 3.0 + h * 8.0, sy - 2.0, 1.2, 1.2, rgba(255, 255, 255, a));
286:             }
287:         }
288:     }
289: }
