291: fn draw_wall(v: &View, tx: i32, ty: i32, wall: u8) {
292:     let x = v.tile_x(tx).floor();
293:     let y = v.tile_y(ty).floor();
294:     let h = hash2(tx, ty, v.seed);
295:     let (base, dark, light) = match wall {
296:         world::WALL_DIRT => (rgb(58, 42, 30), rgb(40, 29, 21), rgb(78, 58, 42)),
297:         world::WALL_STONE => (rgb(38, 40, 46), rgb(27, 28, 34), rgb(52, 54, 62)),
298:         world::WALL_WOOD => (rgb(60, 43, 28), rgb(43, 31, 20), rgb(82, 60, 40)),
299:         _ => (rgb(30, 32, 38), rgb(22, 24, 30), rgb(44, 46, 52)),
300:     };
301:     gfx::rect(x, y, 16.5, 16.5, base);
302:     if wall == world::WALL_WOOD {
303:         gfx::rect(x + 5.0, y, 1.0, 16.0, dark);
304:         gfx::rect(x + 11.0, y, 1.0, 16.0, dark);
305:         if (ty % 3) == 0 {
306:             gfx::rect(x, y + 4.0, 16.0, 1.0, dark);
307:         }
308:     } else if wall == world::WALL_STONE {
309:         if h > 0.45 {
310:             gfx::rect(x + h * 9.0, y + h * 7.0, 2.0 + h * 2.0, 1.6, dark);
311:             gfx::rect(x + 3.0 + h * 6.0, y + 9.0 + h * 4.0, 3.0, 1.0, light);
312:         }
313:         if (tx + ty) % 4 == 0 {
314:             gfx::rect(x, y + 13.0, 16.0, 1.0, dark);
315:         }
316:     } else {
317:         if h > 0.3 {
318:             gfx::rect(x + h * 12.0, y + h * 12.0, 2.0, 2.0, dark);
319:             gfx::rect(x + (1.0 - h) * 12.0, y + (1.0 - h) * 12.0, 1.6, 1.6, light);
320:         }
321:     }
322: }
